WITH flattened AS (SELECT id, plan, effective_from, currency, EXPLODE_OUTER(tier_prices) AS element FROM price_tiers), metrics AS (SELECT plan, effective_from, element, RANK() OVER w_part AS element_rank FROM flattened WINDOW w_part AS (PARTITION BY plan ORDER BY element NULLS FIRST)), scored AS (SELECT *, DENSE_RANK() OVER (ORDER BY element DESC NULLS LAST) AS element_dense_rank FROM metrics), with_windows AS (SELECT *, RANK() OVER (PARTITION BY plan ORDER BY element_dense_rank DESC NULLS LAST) AS element_dense_rank_rank, SUM(element) OVER (PARTITION BY plan) AS plan_sum_element, RANK() OVER (ORDER BY element DESC) AS element_rank_2 FROM scored), metrics_price_tiers AS (SELECT plan, element, element_dense_rank, DENSE_RANK() OVER (ORDER BY element DESC) AS element_dense_rank_2 FROM with_windows) SELECT plan FROM metrics_price_tiers;
